/*
------------------------------------------------------
------------------- ROW + BEHAVIOR -------------------
------------------------------------------------------
*/

// magnet feel, matched to the nav links (MagneticLink) so the row reads as the
// same gesture. STRENGTH = fraction of the center->cursor distance the icon reaches.
const MAGNET_STRENGTH = 0.45;
const MAGNET_SPRING = { stiffness: 200, damping: 12, mass: 0.5 } as const;

// drunk-wander bounds - kept gentle on purpose (Mo: "not crazy"): px of drift and
// degrees of tilt the idle loop roams within before springing back.
const WANDER_DRIFT = 5; // px
const WANDER_TILT = 7; // deg

// slight pop on hover. snappy spring up, then a softer/slower spring back down so
// the shrink lags the grow - same fast-on / lazy-off feel as the scribble ring.
const HOVER_SCALE = 1.14;
const SCALE_SPRING_UP = { type: "spring", stiffness: 380, damping: 17 } as const;
const SCALE_SPRING_DOWN = { type: "spring", stiffness: 210, damping: 22 } as const;

// five hand-drawn-feeling rings so no two adjacent icons get an identical circle.
// each loop overshoots its own start point and wobbles its radius on purpose -
// drawn by a kid, not a compass. it stays wonky on hover (the off-kilter look is
// the whole charm); tilt + stroke-width jitter add extra per-icon variety.
const SCRIBBLE_PATHS = [
  "M50 9 C73 7 95 26 92 49 C94 73 71 95 47 92 C23 94 5 71 9 47 C6 25 27 6 52 11",
  "M52 11 C28 8 8 28 11 52 C8 74 30 95 51 90 C75 94 93 70 89 47 C93 24 72 7 49 12",
  "M48 10 C70 9 93 23 90 47 C95 71 70 96 46 91 C22 95 7 69 10 46 C7 26 25 8 50 13",
  "M50 12 C75 9 92 28 90 50 C92 72 70 94 48 91 C24 93 8 72 11 48 C7 27 28 9 53 9",
  "M51 8 C77 9 94 29 90 52 C93 75 68 96 45 90 C21 93 6 68 11 45 C8 23 27 6 49 13",
] as const;
const SCRIBBLE_TILT = [-6, 5, -3, 8, -9] as const; // deg, so even similar loops read distinct
const SCRIBBLE_WIDTH = [3, 2.7, 3.3, 2.9, 3.1] as const;

/**
 * @description A deliberately imperfect, hand-drawn ring that scribbles itself
 * around an icon - FAST on hover (pathLength snaps on); on leave it erases quickly
 * but the stroke stays opaque until it's nearly retracted, THEN fades. Stays its
 * wonky, off-kilter self the whole time. `variant` picks one of the loops so
 * neighboring icons differ.
 * @author Chris "Mo" Mochinski
 */
function ScribbleCircle({ active, variant }: { active: boolean; variant: number }) {
  const i = variant % SCRIBBLE_PATHS.length;
  return (
    <motion.svg
      className={styles.scribble}
      viewBox="0 0 100 100"
      fill="none"
      aria-hidden
      style={{ rotate: SCRIBBLE_TILT[i] }}>
      <motion.path
        d={SCRIBBLE_PATHS[i]}
        stroke="currentColor"
        strokeWidth={SCRIBBLE_WIDTH[i]}
        strokeLinecap="round"
        initial={false}
        animate={{ pathLength: active ? 1 : 0, opacity: active ? 1 : 0 }}
        transition={{
          // really fast scribble ON, quick-but-lazier unwind OFF
          pathLength: { duration: active ? 0.2 : 0.55, ease: active ? "easeOut" : "easeInOut" },
          // hold the stroke visible while it retracts, then snap-fade near the end
          opacity: active ? { duration: 0.1 } : { duration: 0.16, delay: 0.38 },
        }}
      />
    </motion.svg>
  );
}

interface SocialIconProps {
  label: string;
  href: string;
  Icon: () => React.ReactElement;
  index: number;
  /** only true on hover-capable devices - touch gets a plain, still link */
  magnetic: boolean;
}

/**
 * @description One social icon. Two stacked transform layers keep the gestures
 * from fighting: the outer layer springs toward the cursor (magnet, like the nav
 * links) while the inner layer runs the infinite drunk-wander. On hover the
 * wander settles to neutral and holds, the magnet takes over, and the scribble
 * ring draws on; on leave it all releases and the wander resumes. Per-icon timing
 * is derived from the index so the row never pulses in unison.
 * @author Chris "Mo" Mochinski
 */
function SocialIcon({ label, href, Icon, index, magnetic }: SocialIconProps) {
  const { animationsEnabled } = useReducedMotion();
  const ref = useRef<HTMLAnchorElement>(null);
  const [hovered, setHovered] = useState(false);

  // outer layer: magnet offset toward the cursor, springed for the rubbery settle
  const x = useSpring(0, MAGNET_SPRING);
  const y = useSpring(0, MAGNET_SPRING);
  // inner layer: the drunk wander, driven imperatively so we can pause it on hover
  const wander = useAnimationControls();

  // deterministic per-icon variation so neighbors drift out of phase with each other
  const dir = index % 2 === 0 ? 1 : -1;
  const dur = 5 + (index % 3) * 1.5; // 5 - 8s per loop
  const delay = (index % 4) * 0.4;

  // hovered -> settle to neutral and hold (magnet drives position); idle/released
  // -> roam the gentle drift loop forever. skipped entirely for reduced-motion or
  // touch (no wander machinery on a plain link).
  useEffect(() => {
    if (!animationsEnabled || !magnetic) return;
    if (hovered) {
      void wander.start({
        x: 0,
        y: 0,
        rotate: 0,
        transition: { type: "spring", stiffness: 300, damping: 20 },
      });
      return;
    }
    void wander.start({
      x: [0, WANDER_DRIFT * dir, -WANDER_DRIFT * dir * 0.6, 0],
      y: [0, -WANDER_DRIFT * 0.8, WANDER_DRIFT, 0],
      rotate: [0, WANDER_TILT * dir, -WANDER_TILT * dir, 0],
      transition: {
        duration: dur,
        delay,
        repeat: Infinity,
        repeatType: "mirror",
        ease: "easeInOut",
      },
    });
  }, [hovered, animationsEnabled, magnetic, wander, dir, dur, delay]);

  // touch / no-hover: a plain, still link - no listeners, no stuck hover states
  if (!magnetic) {
    return (
      <a
        className={styles.iconLink}
        href={href}
        target="_blank"
        rel="noreferrer"
        aria-label={label}>
        <span className={styles.iconGlyph}>
          <Icon />
        </span>
      </a>
    );
  }

  function handleMove(e: React.MouseEvent<HTMLAnchorElement>) {
    const rect = ref.current?.getBoundingClientRect();
    if (!rect) return;
    setHovered(true);
    x.set((e.clientX - (rect.left + rect.width / 2)) * MAGNET_STRENGTH);
    y.set((e.clientY - (rect.top + rect.height / 2)) * MAGNET_STRENGTH);
  }

  function reset() {
    setHovered(false);
    x.set(0);
    y.set(0);
  }

  return (
    <a
      ref={ref}
      className={styles.iconLink}
      href={href}
      target="_blank"
      rel="noreferrer"
      aria-label={label}
      onMouseMove={handleMove}
      onMouseLeave={reset}>
      <motion.span
        className={styles.magInner}
        style={{ x, y }}
        animate={{ scale: hovered ? HOVER_SCALE : 1 }}
        transition={{ scale: hovered ? SCALE_SPRING_UP : SCALE_SPRING_DOWN }}>
        <ScribbleCircle active={hovered} variant={index} />
        <motion.span className={styles.iconGlyph} animate={wander}>
          <Icon />
        </motion.span>
      </motion.span>
    </a>
  );
}

/**
 * @description Ordered social destinations. Each row pairs a label (also the
 * link's accessible name) with its URL and inline-SVG icon. The "#" entries are
 * placeholders for the mystery links - swap in real URLs when ready.
 */
