/**
 * @description The contact-page social row: the seven icons centered in a row,
 * each with its drunk-wander + magnet-snap + scribble-circle behavior (touch
 * devices get plain links). Staggers in on mount.
 * @author Chris "Mo" Mochinski
 */
export function SocialRow() {
  const magnetic = useHoverCapable();
  return (
    <motion.div
      className={styles.row}
      initial="hidden"
      animate="shown"
      variants={{ shown: { transition: { staggerChildren: 0.08, delayChildren: 0.15 } } }}>
      {SOCIAL_LINKS.map((s, i) => (
        <motion.div
          key={s.label}
          variants={{
            hidden: { opacity: 0, y: 14, scale: 0.6 },
            shown: {
              opacity: 1,
              y: 0,
              scale: 1,
              transition: { type: "spring", stiffness: 320, damping: 18 },
            },
          }}>
          <SocialIcon label={s.label} href={s.href} Icon={s.Icon} index={i} magnetic={magnetic} />
        </motion.div>
      ))}
    </motion.div>
  );
}
